// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum) public {
        vm.assume(blockNum > 0 && blockNum < type(uint256).max - 1);
        vm.roll(blockNum);
        vm.warp(block.timestamp + 1);
        address sender = address(0x1234);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "call failed");
        uint256 bal = address(c).balance;
        if (blockNum % 15 == 0) {
            assertTrue(bal == 0);
        } else {
            assertTrue(bal == 10 ether);
        }
    }
}
